SELECT DATE_TRUNC('MONTH', ss.sale_date) AS sale_month, ss.product_id, MAX(i.last_restock) AS latest_last_restock, AVG(i.quantity) AS avg_quantity FROM inventory i JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.product_id IN (1, 7) GROUP BY DATE_TRUNC('MONTH', ss.sale_date), ss.product_id ORDER BY avg_quantity, ss.product_id, sale_month LIMIT 1;
